    "mode": "Photo",
    "hdr": "off",
    "filters": "none"
  },
  "aspect_ratio": "9:16",
  "quality": "RAW look, unedited smartphone photo",
  "negative_prompt": "cinematic lighting, HDR look, filters, beauty effects, plastic skin, exaggerated statue size, fake background, tourist postcard style, blur, artificial bokeh, AI artifacts"
}

